#import "AccountAuthClient.h"
#import "CloudURLSession.h"
static void AuthPost(NSString *path, NSDictionary *payload, MSIMEAuthCompletion completion) { if (!path.length || !payload) { if(completion) completion(nil,400,[NSError errorWithDomain:@"MSIMEAuth" code:400 userInfo:nil]); return; } NSMutableURLRequest *r=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:[@"https://api.msime.app" stringByAppendingString:path]]]; r.HTTPMethod=@"POST"; r.HTTPBody=[NSJSONSerialization dataWithJSONObject:payload options:0 error:nil]; [r setValue:@"application/json" forHTTPHeaderField:@"Content-Type"]; [[MSIMECloudURLSession() dataTaskWithRequest:r completionHandler:^(NSData *d, NSURLResponse *response, NSError *e){ dispatch_async(dispatch_get_main_queue(), ^{if(completion)completion(d,[(NSHTTPURLResponse*)response statusCode],e);});}] resume]; }
void MSIMEAuthChallenge(NSString *linkToken, MSIMEAuthCompletion c){NSMutableDictionary*p=[@{@"purpose":linkToken.length?@"link":@"login"}mutableCopy];if(linkToken.length)p[@"link_token"]=linkToken;AuthPost(@"/v1/auth/challenges",p,c);}
void MSIMEAuthLogin(NSString *challenge,NSString *credential,NSString *linkToken,MSIMEAuthCompletion c){if(!challenge.length||!credential.length){if(c)c(nil,400,nil);return;}NSMutableDictionary*p=[@{@"challenge":challenge,@"credential":credential}mutableCopy];if(linkToken.length)p[@"link_token"]=linkToken;AuthPost(@"/v1/auth/login",p,c);}
void MSIMEAuthRefresh(NSString *refreshToken,MSIMEAuthCompletion c){if(!refreshToken.length){if(c)c(nil,400,nil);return;}AuthPost(@"/v1/auth/refresh",@{@"refresh_token":refreshToken},c);}
